  async function uploadSiteImage(file, folder) { if (!file) return null; const safeName = file.name.toLowerCase().replace(/[^a-z0-9._-]+/g, "-"); const path = `${folder}/${crypto.randomUUID()}-${safeName}`; const { error } = await client.storage.from(api.siteMediaBucket).upload(path, file, { upsert: false, contentType: file.type || "application/octet-stream" }); if (error) throw error; return path; }
  const toLocalDate = (value) => { if (!value) return ""; const date = new Date(value); date.setMinutes(date.getMinutes() - date.getTimezoneOffset()); return date.toISOString().slice(0, 16); };
  async function saveEvent(event) { event.preventDefault(); const form = event.currentTarget; const values = Object.fromEntries(new FormData(form)); const old = state.events.find((item) => item.id === form.dataset.id); const imagePath = await uploadSiteImage(form.elements.image.files[0], "events") || old?.image_path || null; const dateValue = (value) => value ? new Date(value).toISOString() : null; const { error } = await client.from("events").upsert({ ...(form.dataset.id ? { id: form.dataset.id } : {}), slug: values.slug || api.slugify(values.title), title: values.title, title_en: values.title_en || null, description: values.description || null, description_en: values.description_en || null, starts_at: dateValue(values.starts_at), ends_at: dateValue(values.ends_at), format: values.format || null, format_en: values.format_en || null, location: values.location || null, location_en: values.location_en || null, teacher: values.teacher || null, teacher_en: values.teacher_en || null, registration_url: values.registration_url || null, payment_url: state.isAdmin ? values.payment_url || null : old?.payment_url ?? null, price_mxn: state.isAdmin ? values.price_mxn ? Number(values.price_mxn) : null : old?.price_mxn ?? null, program_id: values.program_id || null, registration_enabled: form.elements.registration_enabled.checked, image_path: imagePath, event_type: values.event_type, status: values.status, created_by: (await api.current()).user.id }).select().single(); if (error) throw error; toast("Evento guardado."); setTimeout(() => location.href = "/admin/events.html", 500); }
