    const form = `<form class="card card-pad form-grid" data-album-form data-id="${esc(album?.id || "")}"><h2 class="field full">${album?.id ? "Editar álbum" : "Nuevo álbum"}</h2><label class="field">Nombre del álbum<input name="title" required value="${esc(album?.title || "")}"></label>${field("Album title (English)", "title_en", "text", album?.title_en || "")}${field("Descripción", "description", "textarea", album?.description || "")}${field("Description (English)", "description_en", "textarea", album?.description_en || "")}<label class="field">Actividad<select name="event_id">${eventOptions}</select></label>${field("Orden", "sort_order", "number", album?.sort_order ?? 100)}<label class="field">Publicación<select name="status"><option value="DRAFT" ${album?.status !== "PUBLISHED" ? "selected" : ""}>Borrador</option><option value="PUBLISHED" ${album?.status === "PUBLISHED" ? "selected" : ""}>Publicado</option></select></label><label class="field">Fotografía de portada<select name="cover_image_path">${coverOptions}</select><small>La portada reutiliza una fotografía del mismo álbum.</small></label><div class="actions field full"><button class="btn" type="submit">Guardar álbum</button><a class="btn secondary" href="/admin/gallery.html">Volver a álbumes</a></div></form>`;
