    const albumRows = state.albums.map((album) => {
      const count = state.gallery.filter((row) => row.album_id === album.id).length;
      const event = state.events.find((row) => row.id === album.event_id);
      const image = mediaUrl(album.cover_image_path);
      return `<tr><td>${image ? `<img class="gallery-admin-thumb" src="${esc(image)}" alt="" loading="lazy">` : ""}<strong>${esc(album.title)}</strong><div class="meta">${esc(event?.title || "Sin actividad asociada")} · ${count} foto(s)</div></td><td>${accessBadge(album.status)}</td><td>${esc(album.sort_order)}</td><td><a class="link-button" href="/admin/gallery.html?album=${album.id}">Editar álbum</a> <button class="link-button" data-toggle-album="${album.id}" data-status="${album.status === "PUBLISHED" ? "DRAFT" : "PUBLISHED"}">${album.status === "PUBLISHED" ? "Despublicar" : "Publicar"}</button> <button class="link-button" data-delete-album="${album.id}">Eliminar</button></td></tr>`;
    });
    const loose = state.gallery.filter((row) => !row.album_id);
