  async function saveTestimonial(event) { event.preventDefault(); const form = event.currentTarget; const values = Object.fromEntries(new FormData(form)); const old = state.testimonials.find((row) => row.id === form.dataset.id); const imagePath = await uploadSiteImage(form.elements.image.files[0], "testimonials") || old?.image_path || null; const session = await api.current(); const { error } = await client.from("testimonials").upsert({ ...(form.dataset.id ? { id: form.dataset.id } : {}), name: values.name, country: values.country || null, body: values.body, body_en: values.body_en || null, image_path: imagePath, sort_order: Number(values.sort_order) || 100, status: values.status, created_by: session.user.id }).select().single(); if (error) throw error; toast("Testimonio guardado."); setTimeout(() => location.href = "/admin/testimonials.html", 500); }
